import math

class MultilingualSearchEngine:
    def __init__(self, documents: list[str], n: int = 3):
        self.documents = documents
        self.n = n
        self.doc_vectors = [self.char_ngrams(doc) for doc in documents]

    def char_ngrams(self, text: str, n: int = None) -> dict:
        if n is None:
            n = self.n
        text = text.lower()
        counts = {}
        for i in range(len(text) - n + 1):
            gram = text[i:i + n]
            counts[gram] = counts.get(gram, 0) + 1
        return counts

    def cosine_similarity(self, vec_a: dict, vec_b: dict) -> float:
        norm_a = math.sqrt(sum(v * v for v in vec_a.values()))
        norm_b = math.sqrt(sum(v * v for v in vec_b.values()))
        if norm_a == 0 or norm_b == 0:
            return 0.0
        if len(vec_a) > len(vec_b):
            vec_a, vec_b = vec_b, vec_a
        dot = sum(v * vec_b.get(k, 0) for k, v in vec_a.items())
        return dot / (norm_a * norm_b)

    def search(self, query: str, top_k: int = 3) -> list[dict]:
        q = self.char_ngrams(query)
        scored = [
            {"document": doc, "score": self.cosine_similarity(q, vec)}
            for doc, vec in zip(self.documents, self.doc_vectors)
        ]
        scored.sort(key=lambda r: r["score"], reverse=True)
        return scored[:top_k]


# Test it:
engine = MultilingualSearchEngine([
    "machine learning algorithms",
    "deep neural networks",
    "cooking pasta recipes",
    "machine learning models"
])

results = engine.search("machine learning", top_k=2)
print(len(results))
print(results[0]["document"])
print(results[0]["score"] > results[1]["score"])
